-- [HF-PAGES-1] Seed: the 14 policy pages, converted verbatim from web/src/pages/*.astro by scripts/hf_pages_extract.mjs.
-- INSERT OR IGNORE: re-running this never overwrites a page an admin has edited since.
-- Placeholders ({brand.name}, {business.postalAddress} ...) are resolved by the API, not stored resolved.
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('terms','Terms of use','Yeh seva aapko apne favourite influencer se private phone call par jodti hai; istemal se pehle niyam padhein.','[{"href":"/wallet-terms","label":"Wallet terms"},{"href":"/community-guidelines","label":"Community guidelines"},{"href":"/disclaimer","label":"Service disclaimer"},{"href":"/privacy","label":"Privacy policy"}]','[{"t":"h2","text":"Business and contact details"},{"t":"p","spans":[{"text":"The public business name for {brand.name} is {business.name}."}]},{"t":"p","spans":[{"text":"Public postal address: {business.postalAddress}."}]},{"t":"p","spans":[{"text":"For complaints, use the "},{"text":"grievance process","href":"/grievance"},{"text":" or email "},{"text":"{brand.emails.grievance}","href":"mailto:{brand.emails.grievance}"},{"text":"."}]},{"t":"h2","text":"Using the service"},{"t":"p","spans":[{"text":"Read these terms before creating a {brand.name} account or starting a paid conversation. Check the price, availability and eligibility requirements shown before starting a call."}]},{"t":"h2","text":"Account and eligibility"},{"t":"p","spans":[{"text":"For account or service questions, contact "},{"text":"{brand.emails.support}","href":"mailto:{brand.emails.support}"},{"text":"."}]},{"t":"p","spans":[{"text":"The service is intended for adults aged 18 or older in India using their own phone number. Any creator may choose, for free, to take calls only from customers who have completed video KYC. We never share any customer’s details with anyone."}]},{"t":"h2","text":"Conversation and call acceptance"},{"t":"p","spans":[{"text":"Your purchase is time on a private phone call with an influencer, at the per-minute rate set by that influencer and shown before the call. This is not a dating, professional advice, therapy, or emergency service. Influencers must not present a conversation as medical, legal, or financial advice."}]},{"t":"p","spans":[{"text":"The call flow checks eligibility, influencer availability, blocks, account restrictions, and at least ₹20 in your wallet. Our system first calls the influencer and announces that you want to talk. Only if the influencer accepts do we call you and merge the two calls. Both calls come from a {brand.name} number, so your private number is never shared with the influencer, and theirs is never shared with you. A call is made once we have rung both of you and joined the call, and you pay per minute spoken. If the influencer declines, cancels or does not answer, you pay nothing. If a joined call breaks within the first minute, we charge ₹1 and return the rest to your wallet."}]},{"t":"h2","text":"Billing and conduct"},{"t":"p","spans":[{"text":"Billing is by the minute spoken, after we have joined both parties, at the per-minute rate set by the influencer. Read the "},{"text":"wallet terms","href":"/wallet-terms"},{"text":" and "},{"text":"refund policy","href":"/refunds"},{"text":". Every call is recorded for safety and nobody listens live (see "},{"text":"Recording and safety checks","em":true},{"text":" below). Spammy, sexual or threatening behaviour is not allowed, and you can press # to end a call and block the person. See the "},{"text":"safety centre","href":"/safety"},{"text":"."}]},{"t":"p","spans":[{"text":"Follow the "},{"text":"community guidelines","href":"/community-guidelines"},{"text":": no sexual or abusive talk, sharing contact details, selling, financial tips, loans, network marketing, adult services, or payment outside {brand.name}. Influencer controls include ending the call with * and ending the call and blocking the caller with #."}]},{"t":"h2","text":"Wellbeing and the nature of the service"},{"t":"p","spans":[{"text":"The service only connects calls between adults. Influencers are independent individuals, not employees, counsellors or mental-health professionals, and a conversation is not a relationship, therapy or crisis service. You remain responsible for your own decisions and wellbeing. If you are in crisis, call Tele-MANAS 14416 or 112."}]},{"t":"p","spans":[{"text":"To protect callers and influencers, the platform may apply healthy-use limits: a daily time limit with the same influencer, a cooling-off gap between calls to that influencer, and an extra check before large top-ups. The platform may also limit or end contact between a caller and an influencer for wellbeing reasons. A limited caller sees only that the influencer is not available; it is not a decision of the influencer. See "},{"text":"use it in a healthy way","href":"/wellbeing"},{"text":"."}]},{"t":"h2","text":"Your acknowledgement"},{"t":"p","spans":[{"text":"Before first use, callers are asked to confirm: “I understand this is a phone call with an influencer, not counselling, therapy or a relationship service. Influencers are independent people and are not mental-health professionals. If I am in crisis I will call Tele-MANAS 14416 or 112. I am 18 or older.” Before each call, both people hear a short notice: “This is a private call, not counselling. In crisis, dial 14416.”"}]},{"t":"h2","text":"Recording and safety checks"},{"t":"p","spans":[{"text":"Every call is recorded for safety. Nobody listens to a call live. After the call, an AI system turns the recording into text and checks it against our "},{"text":"community guidelines","href":"/community-guidelines"},{"text":". By using the service you agree to this, whether you are a fan or an influencer. Do not share your phone number, UPI ID or address on a call, and never pay anyone outside {brand.name}."}]},{"t":"p","spans":[{"text":"Only named members of our safety team can read the text of a call, and they see only what they need. The "},{"text":"privacy policy","href":"/privacy"},{"text":" says how long each thing is kept."}]},{"t":"h2","text":"Restrictions and review"},{"t":"p","spans":[{"text":"A strike is given for one call and one person, a fan or an influencer. When the AI is very sure a rule was broken, a strike can be given straight away. When it is less sure, our safety team looks first and decides. A strike counts for 90 days. Three active strikes pause the account. Only a person on our team can ban an account. A ban is permanent and the phone number cannot be used to sign up again. Threats, sexual harassment or fraud can mean an immediate ban. If someone may be in danger, we can pause the account at once until our team has looked. Blocks by three distinct influencers trigger a freeze pending review, and two #-ended calls within 24 hours trigger a 24-hour suspension. A mention of self-harm is routed for welfare review, never a strike by itself."}]},{"t":"p","spans":[{"text":"You can appeal each strike once, with the Appeal button in the app (Me, then Safety) or on the website (Dashboard, then Safety). A person reviews it and replies on WhatsApp, and if it is accepted the strike is removed."}]},{"t":"p","spans":[{"text":"When an influencer''s account is paused, new calls and bookings stop, booked calls are cancelled with a full refund to the fans'' wallets, and the influencer''s earnings are held until our review ends. A paused fan cannot call or book but can still sign in and withdraw wallet money. If a ban is confirmed, fans of the flagged calls are refunded first from the held money, and the rest is paid to the influencer''s UPI ID as for a closed account."}]},{"t":"p","spans":[{"text":"A block or safety cut still bills the minutes spoken at the rate shown before the call. Calls that were made are not refunded, except under the first-minute rule, and every refund goes to your wallet, never to your card or UPI. Money is never forfeited as a penalty: a banned account cannot make calls, but can still sign in and withdraw wallet money with the Withdraw button. You may request review of an incorrect restriction through the "},{"text":"grievance process","href":"/grievance"},{"text":"."}]},{"t":"h2","text":"Service limits"},{"t":"p","spans":[{"text":"No particular conversation outcome, uninterrupted connection, or prevention of every harmful interaction is promised. Nothing in these terms is intended to remove rights that cannot lawfully be excluded."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('privacy','Privacy policy','Aapki jaankari ka istemal kaise hota hai, yahan jaanein.','[{"href":"/terms","label":"Terms of use"},{"href":"/grievance","label":"Grievance redressal"},{"href":"/intermediary-policy","label":"Intermediary & content policy"},{"href":"/cookies","label":"Cookies"},{"href":"/data-deletion","label":"Data deletion"}]','[{"t":"h2","text":"Your account and privacy"},{"t":"p","spans":[{"text":"This page describes how account, payment and conversation information is used by {brand.name}. Only provide information needed for the feature you choose to use."}]},{"t":"h2","text":"Privacy questions"},{"t":"p","spans":[{"text":"For privacy questions or data requests, contact "},{"text":"{brand.emails.support}","href":"mailto:{brand.emails.support}"},{"text":". You can also use the "},{"text":"grievance process","href":"/grievance"},{"text":"."}]},{"t":"h2","text":"Information needed for the service"},{"t":"ul","items":[[{"text":"Account and phone-verification details to identify users and connect calls; age and disclaimer acceptance timestamps."}],[{"text":"Call participants, connection and end times, outcome, rate and billing for service delivery, settlement, and safety review."}],[{"text":"A recording of every call, the text made from it, and the result of our safety check (see "},{"text":"Call recordings and safety checks","em":true},{"text":" below)."}],[{"text":"Strikes, appeals and decisions about an account."}],[{"text":"Payment and wallet entries, influencer earnings, reports, influencer blocks and private caller tags, and complaint review records."}],[{"text":"Service WhatsApp messages and replies used for call summaries, blocking, reporting, and caller tags."}],[{"text":"Your voice introduction (if you are an influencer): public on your profile once approved; deleted when you close your influencer account."}]]},{"t":"h2","text":"Number masking and privacy on calls"},{"t":"p","spans":[{"text":"Nobody listens to calls live. Every call is recorded for safety; see "},{"text":"Call recordings and safety checks","em":true},{"text":" below and the "},{"text":"safety centre","href":"/safety"},{"text":"."}]},{"t":"p","spans":[{"text":"Calls are designed to show a service number instead of the other participant''s phone number. Masking does not hide numbers from the service or its telephony provider. Do not share personal contact details during a call."}]},{"t":"h2","text":"Call recordings and safety checks"},{"t":"p","spans":[{"text":"Every call is recorded for safety. The recording is kept in private storage, never on a public page. After the call, an AI system turns it into text (Hindi, Hinglish and other languages) and checks the text against our "},{"text":"community guidelines","href":"/community-guidelines"},{"text":". Women-only calls are recorded and checked in the same way. We use this only to keep people safe and to decide strikes and appeals. We never sell it and never use it for advertising."}]},{"t":"p","spans":[{"text":"Who can read it.","strong":true},{"text":" Only named members of our safety team can read the text of a call. They first see only the flagged line and two lines before and after it. To open the full text they must type a reason, and every opening is logged. A strike message shows you only your own words, never the other person''s."}]},{"t":"p","spans":[{"text":"How long we keep it.","strong":true}]},{"t":"ul","items":[[{"text":"Recording, when the check finds nothing: deleted right after it is turned into text."}],[{"text":"Recording, when the check flags a problem or a fan or influencer reports the call: 30 days."}],[{"text":"Text of the call: 30 days if nothing was found, 1 year if it was flagged."}],[{"text":"Check results, strikes, appeals and decisions: 1 year."}]]},{"t":"p","spans":[{"text":"Records needed for a dispute, payments or a lawful request may be kept for the period the law needs."}]},{"t":"h2","text":"Providers and access"},{"t":"p","spans":[{"text":"Service providers process information needed for authentication, telephony, WhatsApp delivery and payments. Clerk provides account login. Payment details are shown before a purchase. Gemini (Google) transcribes an influencer’s voice introduction for safety checks. Access to call details and reports is restricted to authorised service and safety functions."}]},{"t":"h2","text":"Retention and requests"},{"t":"p","spans":[{"text":"We keep call details (time, length, price, how the call ended) for 1 year, in line with the DPDP Rules 2025, which ask us to keep records for at least one year. Records needed for payments, disputes or lawful requests may be retained for the applicable period."}]},{"t":"p","spans":[{"text":"You may request access, correction, deletion, or a review after identity verification. The "},{"text":"deletion page","href":"/data-deletion"},{"text":" explains the process and its limits. This service is intended only for adults aged 18 or older."}]},{"t":"h2","text":"Data protection law we follow"},{"t":"p","spans":[{"text":"{brand.name} follows India''s Digital Personal Data Protection (DPDP) Act, 2023 and the DPDP Rules, 2025. We never sell your data and never use it for advertising."}]},{"t":"h2","text":"What we collect from callers"},{"t":"ul","items":[[{"text":"Your WhatsApp number, checked with a one-time code."}],[{"text":"The phone number you receive calls on. It can be the same number."}],[{"text":"Wallet top-ups made by UPI."}],[{"text":"Call details: time, length, price and how the call ended."}]]},{"t":"p","spans":[{"text":"Influencers never see your phone number."}]},{"t":"h2","text":"What we collect from influencers"},{"t":"p","spans":[{"text":"Influencers provide a WhatsApp number, withdrawal details (your UPI ID), and a voice introduction that they record themselves. Your voice introduction is public on your profile once our team approves it, and it is deleted when you close your influencer account. Gemini (Google) transcribes introductions so we can check them for phone numbers and other contact details."}]},{"t":"h2","text":"Avatars and AI content"},{"t":"p","spans":[{"text":"To protect influencer privacy, each influencer chooses an avatar. The photos on an influencer profile are AI-generated from that avatar and are labelled as AI. The voice introduction on an influencer profile is the influencer’s own recording, labelled “Recorded by the influencer”. The person you talk to is a real influencer."}]},{"t":"h2","text":"How long we keep data"},{"t":"p","spans":[{"text":"We keep influencer account data while the person is an influencer and for 1 year after, unless another law requires longer. Call details are kept as described in the retention section below."}]},{"t":"h2","text":"Your rights"},{"t":"p","spans":[{"text":"You can see your data, correct it, delete it, withdraw your consent, and nominate someone to act for you. Use the "},{"text":"deletion page","href":"/data-deletion"},{"text":" or write to our "},{"text":"grievance contact","href":"mailto:{brand.emails.grievance}"},{"text":". We reply within the time the law allows, which is 90 days at most."}]},{"t":"h2","text":"Data breaches"},{"t":"p","spans":[{"text":"If a data breach affects you, we will tell you and the Data Protection Board of India, as the law requires."}]},{"t":"h2","text":"Grievance contact"},{"t":"p","spans":[{"text":"To complain about how we handle your data, contact our "},{"text":"grievance contact","href":"/grievance"},{"text":" at "},{"text":"{brand.emails.grievance}","href":"mailto:{brand.emails.grievance}"},{"text":". If you are not satisfied, you can approach the Data Protection Board of India."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('refunds','Refund & cancellation','Jo call ho chuki, uske paise wapas nahi hote. Jo paisa wapas banta hai, woh hamesha aapke wallet mein aata hai.','[{"href":"/wallet-terms","label":"Wallet terms"},{"href":"/terms","label":"Terms of use"},{"href":"/grievance","label":"Grievance redressal"}]','[{"t":"h2","text":"Calls that were made are not refunded"},{"t":"p","spans":[{"text":"{brand.name} does not refund calls that were made. You choose the influencer, you see the rate before you call, and you can hang up at any second. You only pay for the minutes you spoke. The one exception is the first-minute rule below."}]},{"t":"h2","text":"We are not responsible for how a call went"},{"t":"p","spans":[{"text":"{brand.name} connects you with an independent influencer. We are not responsible for your experience with a particular influencer, so we cannot refund a call because the conversation was not what you hoped for. Rate the influencer, try someone else, and "},{"text":"report the influencer","href":"/report"},{"text":" if they broke a rule."}]},{"t":"h2","text":"When you pay nothing"},{"t":"p","spans":[{"text":"A call is made once we have rung both of you and joined the call. Until then, nothing is charged. If the influencer declines, cancels or does not answer, you pay nothing. A call that fails before we join you also costs nothing."}]},{"t":"h2","text":"If a joined call breaks in the first minute"},{"t":"p","spans":[{"text":"If a call breaks within the first minute after we joined you, we charge ₹1 and return the rest to your wallet."}]},{"t":"h2","text":"Booked calls"},{"t":"p","spans":[{"text":"A booked call holds the cost of the first 15 minutes (or of the whole call if it is 15 minutes) in your wallet. You can cancel free until 1 hour before the booked time, and the whole hold comes back to your wallet. After that, the hold is kept. If the influencer does not pick up at the booked time, the full hold comes back to your wallet. If the influencer cancels, it always comes back. If an influencer approves bookings and declines your request, does not accept it in time, or you withdraw it, the full amount comes back too. If you do talk, you pay only for the minutes you spoke and the rest of the hold comes back."}]},{"t":"h2","text":"All call refunds go to your wallet"},{"t":"p","spans":[{"text":"Every refund for a call or a booking goes back to your wallet. We never send a call refund to your card or UPI."}]},{"t":"h2","text":"If an influencer''s account is paused or banned"},{"t":"p","spans":[{"text":"If an influencer''s account is paused, their booked calls are cancelled and the full amount you held goes back to your wallet. If a ban is confirmed, fans of the flagged calls are refunded first from the influencer''s held earnings. Refunds go to your wallet."}]},{"t":"h2","text":"T-shirts from influencers"},{"t":"p","spans":[{"text":"Each T-shirt is printed for you, so we do not take returns or exchanges. If the item arrives wrong or damaged, report it within 48 hours of delivery with a photo, and we will replace it or refund you. If we cannot make your order, you get a full refund. A T-shirt refund goes back the way you paid: to your wallet if you paid from your wallet, and to your payment method if you paid online. You tick this refund policy before you pay for a T-shirt."}]},{"t":"h2","text":"Taking your wallet money out"},{"t":"p","spans":[{"text":"Anyone can withdraw wallet money with the Withdraw button. We send it only to your own UPI ID after a one-time ID (KYC) check, in whole rupees with no fee. Test credits can be spent on calls but cannot be withdrawn. An influencer''s earnings are held for 7 days before they can be withdrawn."}]},{"t":"h2","text":"Billing errors are corrected"},{"t":"p","spans":[{"text":"If you are charged twice for the same call, or charged for a call that was never made, that is a billing error, not a refund request. Report it with the call ID, date and time. It will be checked against the call details and the wrong amount put back in your wallet, linked to that call."}]},{"t":"h2","text":"Information for a billing query"},{"t":"p","spans":[{"text":"Provide the call ID, date and time, amount, transaction reference and a short explanation, and keep your receipt. Never send an OTP, UPI PIN, Aadhaar number or full card details. We will never ask for them. See the "},{"text":"grievance page","href":"/grievance"},{"text":" for how to raise a complaint, and the "},{"text":"help centre","href":"/help"},{"text":" for simple guides on the "},{"text":"refund rules","href":"/help/wallet-and-payments/no-refunds"},{"text":" and "},{"text":"billing mistakes","href":"/help/wallet-and-payments/billing-errors"},{"text":"."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('wallet-terms','Payment & wallet terms','Wallet ka paisa platform par baat karne ke liye hai. Aap use Withdraw button se apne UPI par nikal sakte hain.','[{"href":"/refunds","label":"Refunds"},{"href":"/terms","label":"Terms of use"},{"href":"/grievance","label":"Grievance redressal"}]','[{"t":"h2","text":"Prepaid talk-time wallet"},{"t":"p","spans":[{"text":"Callers add money to a prepaid wallet and spend it on call minutes. The wallet holds rupees. It is for calls on this platform only; it is not a bank account and earns no interest."}]},{"t":"h2","text":"Adding money and GST"},{"t":"p","spans":[{"text":"You can add any whole-rupee amount from ₹10 to ₹5,000. 18% GST is deducted from the amount you pay, so your wallet gets the amount divided by 1.18. For example, if you pay ₹120, your GST of ₹18.31 is deducted and ₹101.69 is added to your wallet. Pay ₹240 and ₹203.39 is added. Pay ₹600 and ₹508.47 is added. Pay ₹1,200 and ₹1,016.95 is added."}]},{"t":"p","spans":[{"text":"Before you pay, you see the total, the GST and the amount added to your wallet. The same three amounts are on your receipt. Money is added only after your payment is confirmed, and only once. No GST is charged again when you spend wallet money on calls."}]},{"t":"h2","text":"Call price and minimum balance"},{"t":"p","spans":[{"text":"Each influencer sets their own per-minute rate, and you see it before you call. You are charged that rate for the minutes you speak. Minutes you have already talked are never charged again at a new price."}]},{"t":"ul","items":[[{"text":"The rate is shown before you start a call."}],[{"text":"You pay by the minute while you are connected."}]]},{"t":"p","spans":[{"text":"You need at least ₹20 in your wallet to start a call. If 5 minutes at the influencer''s rate costs more than ₹20, you need that amount instead. The same applies when you join an influencer''s queue. A call can last up to 5 hours."}]},{"t":"h2","text":"When charges start"},{"t":"p","spans":[{"text":"A call is made once we have rung both of you and joined the call. You are billed by the minute for the time you speak, at the influencer''s rate. Ringing, a declined, cancelled or missed call, and a call that fails before we join you all cost ₹0."}]},{"t":"p","spans":[{"text":"A call goes on until either person hangs up or your wallet money is used up. Money is set aside 5 minutes at a time while you talk, and whatever you do not use comes back to your wallet. If your wallet cannot cover the next 5 minutes, only you hear a voice message that the call will end soon; top up while you are talking and the call keeps going. Your balance can never go below zero."}]},{"t":"p","spans":[{"text":"If a joined call breaks within the first minute, we charge ₹1 and return the rest to your wallet."}]},{"t":"h2","text":"Booked calls"},{"t":"p","spans":[{"text":"A booked call holds the cost of the first 15 minutes (or of the whole call if it is 15 minutes) in your wallet. The rest is charged 5 minutes at a time while you talk, and anything unused comes back. You can cancel free until 1 hour before the booked time. If the influencer does not pick up at the booked time, or if the influencer cancels, the full hold comes back to your wallet. If an influencer approves bookings, your request shows \"Waiting for approval\"; if it is declined or not accepted in time, or you withdraw it, the full amount comes back. If you cancel a confirmed booking later than 1 hour before, the hold is kept."}]},{"t":"h2","text":"Waiting in a queue"},{"t":"p","spans":[{"text":"If an influencer is on a call you can join the queue. Nothing is charged while you wait, and you can leave any time. When their call ends we connect you automatically after about a minute''s break. If you miss our call you are removed from the queue."}]},{"t":"h2","text":"Refunds always go to your wallet"},{"t":"p","spans":[{"text":"We do not refund calls that were made, except under the first-minute rule above. Any call refund we do make goes back to your wallet, never to your card or UPI. T-shirt orders are different: a refund goes back the way you paid, there are no returns, and a wrong or damaged item must be reported within 48 hours of delivery with a photo. Free test credit cannot be used to buy T-shirts. See the "},{"text":"refund policy","href":"/refunds"},{"text":"."}]},{"t":"h2","text":"Withdrawing wallet money"},{"t":"p","spans":[{"text":"Anyone can withdraw wallet money with the Withdraw button. We send it only to your own UPI ID (never a bank account) after a one-time ID (KYC) check. You can withdraw any amount in whole rupees, with no fee, up to 2 times a week. Each request shows its status, and the bank reference (UTR) once it is paid. Test credits can be spent on calls but cannot be withdrawn."}]},{"t":"h2","text":"Closing your account"},{"t":"p","spans":[{"text":"When you close your account we settle your money first: your wallet balance is paid to your own UPI ID in whole rupees (the part below ₹1 is not paid), and your account is deleted after 30 days. Earnings still in the 7-day hold are paid on their release date."}]},{"t":"h2","text":"Influencer earnings"},{"t":"p","spans":[{"text":"Influencers earn a share of the rate for every minute spoken. We keep ₹2 a minute plus 40% of the rate above ₹2, and the influencer keeps the rest. Earnings are held for 7 days, then they can be withdrawn with the Withdraw button."}]},{"t":"h2","text":"Paused accounts"},{"t":"p","spans":[{"text":"If your account is paused, you cannot call or book, but you can still sign in and withdraw your wallet money with the Withdraw button. If an influencer''s account is paused, their booked calls are cancelled with a full refund to your wallet, and their earnings are held until our review ends. If a ban is confirmed, fans of the flagged calls are refunded first from their held earnings, and the rest is paid to their UPI ID as for a closed account."}]},{"t":"h2","text":"Ended calls, bans and disputes"},{"t":"p","spans":[{"text":"A call ended by either person, by # or by a safety action bills the minutes spoken up to that moment. If an account is banned, it can no longer make or receive calls, but the owner can still sign in and withdraw wallet money with the Withdraw button. Money is never forfeited as a penalty."}]},{"t":"p","spans":[{"text":"See "},{"text":"refunds and billing errors","href":"/refunds"},{"text":" for incorrect charges, and "},{"text":"grievance redressal","href":"/grievance"},{"text":" to ask for a review of an account restriction."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('community-guidelines','Community guidelines','Izzat se baat karein; har insaan ki hadon ka dhyaan rakhein.','[{"href":"/terms","label":"Terms of use"},{"href":"/grievance","label":"Grievance redressal"}]','[{"t":"p","spans":[{"text":"These guidelines apply to conversations and account activity. Respect other people and use the available reporting controls when something goes wrong."}]},{"t":"h2","text":"What is welcome"},{"t":"p","spans":[{"text":"Adults aged 18 or older can talk to their favourite influencers over a private call and discuss a shared interest. Astrology and tarot are for reflection and entertainment, with no promised outcomes. Respect a person''s decision to decline, end or change the topic."}]},{"t":"p","spans":[{"text":"With an influencer who lists women''s health as a topic on their profile, everyday health experiences are a normal topic (see "},{"text":"women''s safety","href":"/women-only"},{"text":"). Discussing periods, PCOS or pregnancy is not in itself sexual misconduct. Harassment is still reportable. Influencers must not provide medical advice, diagnosis or treatment."}]},{"t":"h2","text":"What is not allowed"},{"t":"ul","items":[[{"text":"Abuse, gaali, threats, harassment or coercion."}],[{"text":"Sexual or suggestive talk, and any adult services."}],[{"text":"Selling anything on a call: products, services, courses or remedies. Influencers can sell through the {brand.name} Shop instead."}],[{"text":"Financial tips, loans, investment or money-making schemes, and network marketing (MLM)."}],[{"text":"Asking for or taking payment outside {brand.name}. Never pay or get paid by UPI, bank transfer or cash outside the app."}],[{"text":"Sharing or asking for phone numbers, UPI IDs, addresses, social accounts or other contact details, or arranging meetings."}],[{"text":"Impersonation, false qualifications, or professional medical or legal advice."}],[{"text":"Using the service under 18, sharing another person''s private information."}]]},{"t":"h2","text":"How reports and strikes work"},{"t":"p","spans":[{"text":"Influencers can end a call with "},{"text":"*","strong":true},{"text":", or use "},{"text":"#","strong":true},{"text":" to end, block the caller from that influencer and flag an incident. A block stops future contact with that influencer; it does not by itself prove misconduct or permanently ban an account."}]},{"t":"p","spans":[{"text":"Every call is recorded for safety. Nobody listens live.","strong":true},{"text":" After the call, an AI system turns the recording into text and checks it against these guidelines. Women-only calls are recorded and checked in the same way. Read what we keep, for how long and who can read it in the "},{"text":"privacy policy","href":"/privacy"},{"text":"."}]},{"t":"p","spans":[{"text":"A report from a fan or an influencer also sends the call for a check. A report is only a report until it is reviewed. Mentions of self-harm go to welfare review and must never count as a strike."}]},{"t":"h2","text":"Strikes"},{"t":"p","spans":[{"text":"A strike is given for one call and one person, a fan or an influencer. When the AI is very sure a rule was broken, the strike can be given straight away. When it is less sure, our safety team looks first. The person gets a message that says what happened and how to appeal, and sees only their own words."}]},{"t":"ul","items":[[{"text":"A strike counts for "},{"text":"90 days","strong":true},{"text":", then it expires."}],[{"text":"Three active strikes pause the account.","strong":true},{"text":" A paused influencer is hidden, and calls, the queue and new bookings stop. Booked calls are cancelled and the fans get a full refund to their wallets. A paused fan cannot call or book but can still sign in and withdraw wallet money."}],[{"text":"Appeal once per strike.","strong":true},{"text":" Tap Appeal in the app (Me, then Safety) or on the website (Dashboard, then Safety). A person reviews it and replies on WhatsApp. If it is accepted, the strike is removed."}],[{"text":"Only a person can ban an account.","strong":true},{"text":" A ban is permanent and the phone number cannot be used to sign up again. Threats, sexual harassment, fraud or danger to someone can lead to a pause or an immediate ban."}]]},{"t":"p","spans":[{"text":"Blocking by three distinct influencers can freeze the caller account pending review; two calls ended with the influencer''s # key within 24 hours can trigger a 24-hour suspension. These controls cannot guarantee that harm will be detected."}]},{"t":"h2","text":"Money when an account is paused or banned"},{"t":"p","spans":[{"text":"A paused influencer''s earnings are held until our review ends. If a ban is confirmed, fans of the flagged calls are refunded first from the held money, and the rest is paid to the influencer''s UPI ID as for a closed account. A banned fan can still sign in and withdraw wallet money with the Withdraw button. Minutes already spoken remain billable under the "},{"text":"wallet terms","href":"/wallet-terms"},{"text":"."}]},{"t":"h2","text":"On a call"},{"t":"p","spans":[{"text":"Spammy, sexual or threatening behaviour is not allowed. Do not share your phone number, UPI ID or address, and never pay outside {brand.name}; if someone asks, say no and report it after the call. You can end any call yourself, or press # to end the call and block the person. We never ask for OTP, UPI PIN, passwords or bank details; if anyone does, report them."}]},{"t":"p","spans":[{"text":"Influencers also follow the "},{"text":"influencer rules","href":"/hosts/rules"},{"text":". See "},{"text":"Report a user","href":"/report"},{"text":" for reporting availability and "},{"text":"grievance redressal","href":"/grievance"},{"text":" for the published route to challenge account action. Reporting an incident does not guarantee a particular outcome."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('disclaimer','Service disclaimer','Yahan sirf baat hoti hai, peshevar salah nahi.','[{"href":"/terms","label":"Terms of use"},{"href":"/emergency","label":"Emergency support"}]','[{"t":"h2","text":"Service limits"},{"t":"p","spans":[{"text":"{brand.name} connects adults aged 18 or older with their favourite social media influencers over a private phone call. Check the price, availability and eligibility requirements shown before starting a call."}]},{"t":"p","spans":[{"text":"Conversations are not medical, legal, financial, counselling, or other professional advice. Influencers must not present themselves as providing professional care. Astrology and tarot conversations are for reflection and entertainment, with no promised outcome. Do not rely on an influencer for an emergency response."}]},{"t":"h2","text":"Not a relationship or crisis service"},{"t":"p","spans":[{"text":"Influencers are independent individuals offering paid phone calls. They are not partners, counsellors or mental-health professionals, and {brand.name} is not a dating, relationship or crisis service. Each person is responsible for their own decisions. The platform may apply healthy-use limits and may limit contact for wellbeing reasons; see "},{"text":"use it in a healthy way","href":"/wellbeing"},{"text":". In crisis, call Tele-MANAS 14416 or 112."}]},{"t":"h2","text":"Safety controls"},{"t":"p","spans":[{"text":"No human monitors or listens to live calls. Reports are reviewed by our team. Influencers can end a call with * or end the call and block the caller with #. These controls cannot guarantee prevention of harm."}]},{"t":"p","spans":[{"text":"Sexual or abusive conduct leads to review and restrictions. The ban threshold is three confirmed strikes, based on reports reviewed by our team; threats, sexual harassment or fraud can mean an immediate ban. Self-harm mentions are routed for welfare review, not punished with a strike."}]},{"t":"h2","text":"हिन्दी"},{"t":"p","lang":"hi","spans":[{"text":"{brand.nameHindi} वयस्कों (18+) को उनके पसंदीदा सोशल मीडिया इन्फ्लुएंसर से निजी फ़ोन कॉल पर जोड़ने वाली सेवा है। कॉल शुरू करने से पहले कीमत, उपलब्धता और पात्रता की शर्तें पढ़ें। यहाँ की बातचीत चिकित्सा, कानूनी, वित्तीय या मानसिक स्वास्थ्य की पेशेवर सलाह नहीं है। ज्योतिष और टैरो में किसी नतीजे का वादा नहीं किया जाता।"}]},{"t":"p","lang":"hi","spans":[{"text":"कोई इंसान लाइव कॉल की निगरानी नहीं करता या उसे नहीं सुनता; रिपोर्ट हमारी टीम देखती है। इन्फ्लुएंसर * से कॉल खत्म कर सकेगा और # से कॉल खत्म करके कॉलर को ब्लॉक कर सकेगा। इन्फ्लुएंसर स्वतंत्र लोग हैं — वे साथी, काउंसलर या मानसिक स्वास्थ्य विशेषज्ञ नहीं हैं, और यह डेटिंग या संकट सेवा नहीं है। संकट में टेली-मानस 14416 या 112 पर कॉल करें। स्ट्राइक हमारी टीम द्वारा जाँची गई रिपोर्ट पर आधारित होते हैं; तीन पुष्ट स्ट्राइक पर बैन होता है। आत्महानि का ज़िक्र अपने आप स्ट्राइक का कारण नहीं है। ये नियंत्रण पूरी सुरक्षा की गारंटी नहीं देते।"}]},{"t":"p","spans":[{"text":"For urgent help, see "},{"text":"emergency support","href":"/emergency"},{"text":". Platform reports and welfare review are not emergency services."}]}]',1,'2026-10-15',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('rules-of-engagement','Rules of engagement','Clear boundaries for respectful, private conversations.','[{"href":"/community-guidelines","label":"Community guidelines"},{"href":"/privacy","label":"Privacy policy"}]','[{"t":"h2","text":"Be respectful"},{"t":"p","spans":[{"text":"Speak to every person with dignity. Harassment, threats, hateful conduct, sexual pressure and abusive language are not allowed."}]},{"t":"h2","text":"Keep personal contact details private"},{"t":"p","spans":[{"text":"Do not ask for or share phone numbers, UPI IDs, email addresses, social handles, home addresses or off-platform meeting details during a call."}]},{"t":"h2","text":"Do not sell, and never pay outside"},{"t":"p","spans":[{"text":"Do not sell products, services or courses on a call, and do not give financial tips, loans or network-marketing offers. Influencers can use the {brand.name} Shop to sell. Never ask for or send money outside {brand.name}. If someone asks you to, say no and report it after the call."}]},{"t":"h2","text":"Respect consent and boundaries"},{"t":"p","spans":[{"text":"Either person may end a call at any time. An influencer may decline a call, and a caller may choose not to continue. Do not pressure someone to stay."}]},{"t":"h2","text":"Use the service for calls with influencers"},{"t":"p","spans":[{"text":"Calls are conversations, not medical, legal, financial or emergency services. Do not promise diagnoses, guaranteed outcomes or emergency response."}]},{"t":"h2","text":"Protect call privacy"},{"t":"p","spans":[{"text":"Every call is recorded for safety and checked by AI after the call. Nobody listens live. Do not share or redistribute anything said on a call. Follow the "},{"text":"safety centre","href":"/safety"},{"text":" guidance, and report conduct that breaks these rules."}]},{"t":"h2","text":"Reviews must be genuine"},{"t":"p","spans":[{"text":"Only review a call you genuinely joined. Describe your own experience without contact details, private information or abuse."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('grievance','Grievance redressal','Shikayat aur uski jaanch ka prastaavit tareeqa yahan padhein.','[{"href":"/intermediary-policy","label":"Intermediary & content policy"},{"href":"/privacy","label":"Privacy policy"},{"href":"/terms","label":"Terms of use"}]','[{"t":"h2","text":"How to complain"},{"t":"p","spans":[{"text":"A page or report form is not confirmation that a complaint has been submitted or received. You can email a complaint to the grievance contact below."}]},{"t":"h2","text":"Grievance contact"},{"t":"p","spans":[{"text":"Business name:","strong":true},{"text":" {business.name}"},{"text":"\n"},{"text":"Email:","strong":true},{"text":" "},{"text":"{brand.emails.grievance}","href":"mailto:{brand.emails.grievance}"},{"text":"\n"},{"text":"Public postal address:","strong":true},{"text":" {business.postalAddress}"}]},{"t":"h2","text":"What a complaint should include"},{"t":"p","spans":[{"text":"Include your registered contact details, the relevant profile, call ID or payment reference, date and time, the issue, and the outcome you are asking for. Do not send passwords, OTPs, UPI PINs or Aadhaar numbers. The "},{"text":"report page","href":"/report"},{"text":" explains call-safety reporting."}]},{"t":"h2","text":"How we review"},{"t":"p","spans":[{"text":"Complaints may concern conduct, a block or strike, a suspension or ban, charges, or deletion. We check the relevant call, billing, and moderation records and communicate the outcome. Pending reports are not the same as confirmed strikes. Self-harm mentions are for welfare follow-up, not a strike."}]},{"t":"h2","text":"Escalation and urgent help"},{"t":"p","spans":[{"text":"Nothing here limits your legal remedies. For immediate danger, use the "},{"text":"emergency support page","href":"/emergency"},{"text":"; platform reports are not an emergency response service."}]}]',1,'2026-10-15',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('safety','Safety centre','Pehle niyam samjhein, apni hadon ka dhyaan rakhein.','[]','[{"t":"h2","text":"How calls are kept safe"},{"t":"p","spans":[{"text":"We call the influencer first and announce that you want to talk. The influencer chooses whether to accept before you are dialled. Both calls come from a platform number, so your private number and the influencer''s stay hidden. Either person can hang up at any time; pressing "},{"text":"#","strong":true},{"text":" ends the call and blocks the other person."}]},{"t":"p","spans":[{"text":"Every call is recorded for safety, and nobody listens live. After the call, an AI system checks the recording. Very clear rule breaks can get a strike straight away; anything unclear goes to our safety team first. Only a person can ban an account. You can also report and block anyone. Do not share your phone number, UPI ID or address, and never pay anyone outside {brand.name}: if someone asks, say no and report it after the call. Watch out for scams: anyone who asks you for an OTP, UPI PIN, password, card or bank details is a scammer. The platform never asks for them. Talking about distress is never a reason for a strike."}]},{"t":"p","spans":[{"text":"You do not owe anyone your number, identity documents, money, private contact or another minute of conversation. Leave if you feel uncomfortable. The "},{"text":"women''s safety guide","href":"/women-only"},{"text":" explains Women-only channels, boundaries and respectful discussion of women''s experiences. Most questions are answered in the "},{"text":"FAQs","href":"/faq"},{"text":"."}]},{"t":"h2","text":"Safety guides"},{"t":"links","items":[{"href":"/community-guidelines","title":"Community guidelines","text":"Boundaries, recording, strikes, appeals and bans."},{"href":"/help/safety-and-privacy/are-calls-recorded","title":"Are calls recorded?","text":"What we record, who can read it and how long we keep it."},{"href":"/help/safety-and-privacy/how-to-appeal-a-strike","title":"Appeal a strike","text":"One appeal for each strike, reviewed by a person."},{"href":"/talk-safely","title":"Talk safely","text":"Ways to protect your privacy on a call."},{"href":"/report","title":"Report a user","text":"How to report someone after a call."},{"href":"/grievance","title":"Grievance redressal","text":"Published contacts and how to raise a concern."},{"href":"/wellbeing","title":"Use it in a healthy way","text":"Healthy limits, influencers and fans, getting real help."},{"href":"/emergency","title":"Emergency support","text":"Help outside the platform for urgent situations."},{"href":"/women-only","title":"Women''s safety","text":"Women-only channels, boundaries and respectful talk."},{"href":"/lgbtq","title":"LGBTQ+ safety","text":"LGBTQ+ channels and LGBTQ+ friendly influencers."},{"href":"/age-policy","title":"Age policy","text":"The 18+ rule."},{"href":"/child-safety","title":"Child safety standards","text":"Zero tolerance for child abuse, and how to report it."}]},{"t":"h2","text":"Urgent help comes from outside this site"},{"t":"p","spans":[{"text":"For immediate danger in India, call "},{"text":"Emergency 112","href":"tel:112"},{"text":". For mental-health support, call "},{"text":"Tele-MANAS 14416","href":"tel:14416"},{"text":". Reports here are not an emergency service. Official information: "},{"text":"112","href":"https://112.gov.in/"},{"text":" and "},{"text":"Tele-MANAS","href":"https://dghs.mohfw.gov.in/national-mental-health-programme.php"},{"text":"."}]}]',1,'2026-10-28',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('cookies','Cookie policy','Zaroori cookies sign-in aur suraksha mein madad karti hain.','[]','[{"t":"h2","text":"Essential cookies"},{"t":"p","spans":[{"text":"Essential cookies and similar browser storage keep you signed in, protect your session, and remember choices needed to run the service. Clerk may use cookies for account access. Blocking these may prevent sign-in or other features from working."}]},{"t":"h2","text":"Analytics"},{"t":"p","spans":[{"text":"If optional analytics are used, they help us understand how pages perform and where users encounter problems. Any required choice or consent will be presented before optional cookies are used. This page does not mean every type of analytics is enabled."}]},{"t":"h2","text":"Your choices"},{"t":"p","spans":[{"text":"Use the site''s cookie controls, where available, to change optional choices. You can also block or delete cookies in your browser settings. Deleting cookies may sign you out. Contact "},{"text":"{brand.emails.support}","href":"mailto:{brand.emails.support}"},{"text":" if you need help with a cookie or privacy choice."}]},{"t":"p","spans":[{"text":"Read the "},{"text":"privacy policy","href":"/privacy"},{"text":" for the data we use and your rights."}]}]',1,'2026-10-15',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('data-deletion','Data deletion','Account aur apni jaankari hatane ka anurodh kar sakte hain.','[]','[{"t":"h2","text":"How deletion works"},{"t":"p","spans":[{"text":"When your account deletion is processed, we remove your withdrawal details, your voice intro and your profile media and your influencer profile. Reviews you wrote or received are removed too. Your public profile stops being shown."}]},{"t":"h2","text":"Your money is paid out first"},{"t":"p","spans":[{"text":"If you still have real money in your wallet, withdraw it with the Withdraw button before you close your account, so you never lose money by closing it. We send it to your UPI after a one-time ID (KYC) and UPI check. Influencer earnings still inside the 7-day hold can be withdrawn when the hold ends. Test credits are not real money and are simply removed."}]},{"t":"p","spans":[{"text":"Deletion completes after your money is settled. Each payment is approved by a person, so this can take a few days. You can start it, see its progress, or cancel it (until a payment has been approved) at "},{"text":"Close my account","href":"/account/close"},{"text":". If you have no money to settle, deletion starts straight away and follows the steps below."}]},{"t":"h2","text":"Requesting deletion"},{"t":"p","spans":[{"text":"Email "},{"text":"{brand.emails.support}","href":"mailto:{brand.emails.support}"},{"text":" for deletion requests. Identify the account using its registered contact details. Identity must be verified before deletion. Never email an OTP or Aadhaar number."}]},{"t":"h2","text":"What is removed"},{"t":"p","spans":[{"text":"Account deletion removes withdrawal details, voice intro and profile media. Call details (time, length, price, how the call ended) and safety flags are kept for 1 year for safety and legal reasons, then deleted."}]},{"t":"p","spans":[{"text":"Unused balance is handled as described above and under the "},{"text":"refund terms","href":"/refunds"},{"text":": all refunds go to your wallet, and you can withdraw wallet money with the Withdraw button."}]},{"t":"h2","text":"Records that may remain"},{"t":"p","spans":[{"text":"Call details and safety logs are kept for 1 year, in line with the DPDP Rules 2025, which ask us to keep records for at least one year, and then deleted. Payment records, unresolved disputes, and lawful preservation requests may require different treatment. Any retained records should have restricted access and must not keep a deleted profile publicly active."}]},{"t":"p","spans":[{"text":"After three confirmed strikes, a phone-number restriction may be kept to prevent re-registration."}]},{"t":"h2","text":"Instagram login data"},{"t":"p","spans":[{"text":"If you remove {brand.name} in your Instagram settings, or ask Instagram to delete your data, we delete the Instagram login we held for your account and the comments we imported from your reels, and we hide those reels. Comments that our own users replied to stay, with their text replaced by \"Comment removed\". You can also press Remove on your channel inside the app."}]},{"t":"h2","text":"Confirmation and review"},{"t":"p","spans":[{"text":"Read the "},{"text":"privacy policy","href":"/privacy"},{"text":" and "},{"text":"grievance process","href":"/grievance"},{"text":" for more."}]}]',1,'2026-10-19',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('age-policy','Age policy','Callers aur influencers, sabhi ka 18 saal ya usse zyada hona zaroori hai.','[]','[{"t":"h2","text":"Adults only"},{"t":"p","spans":[{"text":"You must be at least 18 to call, or to be an influencer, on {brand.name}. An adult must not let a child use their account."}]},{"t":"h2","text":"How age is checked"},{"t":"p","spans":[{"text":"Everyone declares their age at sign-up. Do not use another person''s details."}]},{"t":"h2","text":"If we find a minor"},{"t":"p","spans":[{"text":"We close the account. Its remaining wallet balance can be withdrawn with the Withdraw button after the usual ID and UPI checks. We may ask for information needed to verify the account and process that withdrawal safely."}]},{"t":"p","spans":[{"text":"If you believe a user is under 18, "},{"text":"report the profile or call","href":"/report"},{"text":". Do not ask them to send you identity documents. See our "},{"text":"privacy policy","href":"/privacy"},{"text":" for how your data is handled."}]}]',1,'2026-10-19',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('child-safety','Child safety standards','Bachchon ki suraksha: zero tolerance. Hum har report par turant kaam karte hain.','[]','[{"t":"h2","text":"Zero tolerance for child sexual abuse and exploitation"},{"t":"p","spans":[{"text":"{brand.name} has zero tolerance for child sexual abuse and exploitation (CSAE) and child sexual abuse material (CSAM). Any content, call, message, profile or behaviour that sexualises, grooms, exploits or endangers a child is banned on our app and website."}]},{"t":"h2","text":"Adults only"},{"t":"p","spans":[{"text":"{brand.name} is for people aged 18 and over. Callers and influencers must be adults. If we find that an account belongs to someone under 18, we close it. See our "},{"text":"age policy","href":"/age-policy"},{"text":"."}]},{"t":"h2","text":"What is not allowed"},{"t":"ul","items":[[{"text":"Sharing, asking for or linking to any sexual image or video of a person under 18."}],[{"text":"Grooming: building trust with a child to abuse or exploit them, or asking a child to move to another app."}],[{"text":"Sexual talk with, or about, a child, including role-play."}],[{"text":"Sextortion, trafficking or any offer of a child for sexual purposes."}]]},{"t":"h2","text":"What we do"},{"t":"ul","items":[[{"text":"We remove the content and permanently ban the account, with no warning or strike."}],[{"text":"We keep the relevant records and report CSAM and child exploitation to the authorities in India, including the National Cybercrime Reporting Portal ("},{"text":"cybercrime.gov.in","href":"https://cybercrime.gov.in/"},{"text":") and the police, as Indian law requires."}],[{"text":"We cooperate with law-enforcement requests made under Indian law."}]]},{"t":"h2","text":"How to report"},{"t":"p","spans":[{"text":"In the app, open the profile or call and use "},{"text":"Report","strong":true},{"text":", pick \"Inappropriate talk or behaviour\" and write \"child safety\" in the note. You can also "},{"text":"report on the website","href":"/report"},{"text":" or email our designated child-safety contact below. Do not download, save or forward the material yourself."}]},{"t":"p","spans":[{"text":"Child safety contact:","strong":true},{"text":" "},{"text":"{brand.emails.grievance}","href":"mailto:{brand.emails.grievance}"},{"text":" (Grievance Officer). We act on child-safety reports as a priority."}]},{"t":"p","spans":[{"text":"If a child is in immediate danger in India, call "},{"text":"112","href":"tel:112"},{"text":". You can also call the Childline "},{"text":"1098","href":"tel:1098"},{"text":"."}]},{"t":"p","spans":[{"text":"Related: "},{"text":"community guidelines","href":"/community-guidelines"},{"text":", "},{"text":"safety centre","href":"/safety"},{"text":", "},{"text":"privacy policy","href":"/privacy"},{"text":"."}]}]',1,'2026-10-24',1,'seed');
INSERT OR IGNORE INTO site_pages (slug,title,summary,related,body,version,updated_at,published,updated_by) VALUES ('intermediary-policy','Intermediary & content policy','Galat content ki report aur kanooni requests ka process yahan hai.','[{"href":"/community-guidelines","label":"Community guidelines"},{"href":"/grievance","label":"Grievance redressal"},{"href":"/terms","label":"Terms of use"},{"href":"/privacy","label":"Privacy policy"}]','[{"t":"h2","text":"Our role"},{"t":"p","spans":[{"text":"{brand.name} provides a platform that connects users with social media influencers for private phone calls. This policy sets out its intended intermediary role under section 79 of the Information Technology Act and the IT Rules 2021. Any legal protection depends on meeting the conditions in the law; it is not automatic."}]},{"t":"h2","text":"Due diligence"},{"t":"p","spans":[{"text":"Our safety measures include number masking, a strike system, a grievance contact, and published community guidelines. Users must not share illegal content, threaten others, impersonate someone, or breach the "},{"text":"community guidelines","href":"/community-guidelines"},{"text":"."}]},{"t":"h2","text":"Reports and action"},{"t":"ol","items":[[{"text":"Send a report with the profile name, call ID or content location, and a description of the concern."}],[{"text":"Trust & Safety reviews the report and relevant records. We may ask for more information."}],[{"text":"We may restrict access, take down content, end a call, or suspend an account as appropriate. We preserve records when legally required."}],[{"text":"We respond to valid legal orders and requests within the applicable legal deadlines. Users may request review through the grievance process."}]]},{"t":"h2","text":"Law-enforcement contact"},{"t":"p","spans":[{"text":"Send lawful requests to "},{"text":"{brand.emails.grievance}","href":"mailto:{brand.emails.grievance}"},{"text":". Include the requesting authority, legal basis, relevant account or call identifiers, scope, and contact details for verification. We assess requests under applicable law and disclose only as legally required."}]},{"t":"p","spans":[{"text":"For ordinary complaints, use "},{"text":"Report a user","href":"/report"},{"text":" or contact the "},{"text":"grievance contact","href":"/grievance"},{"text":"."}]}]',1,'2026-10-15',1,'seed');
